import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:uuid/uuid.dart';import '../../../app/providers.dart';import '../../../core/widgets/app_async_state.dart';import '../../../data/models/chat/message_model.dart';import '../../../data/repositories/chat_repository.dart';
final messagesProvider=StreamProvider.family<List<MessageModel>,String>((ref,id)=>ref.watch(chatRepositoryProvider).watchMessages(id));
class ChatScreen extends ConsumerStatefulWidget{const ChatScreen({super.key,required this.conversationId});final String conversationId;@override ConsumerState<ChatScreen> createState()=>_ChatScreenState();}class _ChatScreenState extends ConsumerState<ChatScreen>{final _input=TextEditingController();String? _replyTo;@override void dispose(){_input.dispose();super.dispose();}Future<void> _send()async{final uid=ref.read(authStateProvider).valueOrNull?.uid;final text=_input.text.trim();if(uid==null||text.isEmpty||widget.conversationId.isEmpty)return;_input.clear();await ref.read(chatRepositoryProvider).send(MessageModel(id:const Uuid().v4(),conversationId:widget.conversationId,senderId:uid,text:text,type:MessageType.text,createdAt:DateTime.now(),replyToMessageId:_replyTo));setState(()=>_replyTo=null);}@override Widget build(BuildContext context){final state=ref.watch(messagesProvider(widget.conversationId));final uid=ref.watch(authStateProvider).valueOrNull?.uid;return Scaffold(appBar:AppBar(title:const Text('المحادثة')),body:Column(children:[Expanded(child:state.when(loading:()=>const AppLoading(),error:(e,_)=>AppErrorState(message:'تعذر تحميل الرسائل.',onRetry:()=>ref.invalidate(messagesProvider(widget.conversationId))),data:(items)=>items.isEmpty?const AppEmptyState(title:'ابدأ المحادثة',message:'أرسل رسالة لبدء الاستشارة.',icon:Icons.chat_bubble_outline):ListView.builder(padding:const EdgeInsets.all(12),itemCount:items.length,itemBuilder:(_,index){final message=items[index];final mine=message.senderId==uid;return Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:GestureDetector(onLongPress:()=>setState(()=>_replyTo=message.id),child:Card(color:mine?Theme.of(context).colorScheme.primaryContainer:null,child:Padding(padding:const EdgeInsets.all(12),child:Text(message.isDeleted?'تم حذف هذه الرسالة':message.text))));}))),if(_replyTo!=null)ListTile(leading:const Icon(Icons.reply),title:const Text('الرد على رسالة'),trailing:IconButton(onPressed:()=>setState(()=>_replyTo=null),icon:const Icon(Icons.close))),SafeArea(child:Padding(padding:const EdgeInsets.all(10),child:Row(children:[IconButton(onPressed:(){},icon:const Icon(Icons.attach_file),tooltip:'إرفاق ملف'),Expanded(child:TextField(controller:_input,onChanged:(value){if(uid!=null&&widget.conversationId.isNotEmpty){ref.read(chatRepositoryProvider).setTyping(widget.conversationId,uid,value.isNotEmpty);}},onSubmitted:(_)=>_send(),decoration:const InputDecoration(hintText:'اكتب رسالة…'))),IconButton(onPressed:_send,icon:const Icon(Icons.send))]))) ]));}}
